def cmd_connect(args: argparse.Namespace) -> int:
    """Connect Scubiee to AI coding tools (MCP config + rules)."""
    from pipeline.rules_installer import install_tools
    from pipeline.tool_registry import ALL_SLUGS, CONNECT_SLUGS, normalize_tool_slug

    # Collect selected tools
    if getattr(args, "all", False):
        selected = list(ALL_SLUGS)
    else:
        selected = []
        for slug in CONNECT_SLUGS:
            if getattr(args, slug.replace("-", "_"), False):
                selected.append(normalize_tool_slug(slug))
        seen: set[str] = set()
        selected = [s for s in selected if not (s in seen or seen.add(s))]

    if not selected:
        if sys.stdout.isatty():
            from pipeline.cli_ui import error, info
            error("No tools specified", stream=sys.stderr)
            info(f"Use --all or specify tools: {', '.join(f'--{s}' for s in ALL_SLUGS[:4])}...", stream=sys.stderr)
            sys.stderr.write("\n")
        else:
            print(json.dumps({"ok": False, "error": "no tools specified"}, indent=2))
        return 1

    dry_run = getattr(args, "dry_run", False)
    repo = getattr(args, "repo", None)
    results = install_tools(selected, dry_run=dry_run, repo=repo)

    if sys.stdout.isatty():
        from pipeline.cli_ui import print_connect_summary

        print_connect_summary(results, action="Connected", dry_run=dry_run)
    else:
        print(json.dumps(results, indent=2, default=str))

    fail_count = sum(1 for r in results if not r.get("ok"))
    return 0 if fail_count == 0 else 1

def install_tools(
    slugs: list[str],
    *,
    dry_run: bool = False,
    repo: Path | str | None = None,
) -> list[dict[str, Any]]:
    results = []
    for slug in slugs:
        tool = get_tool(slug)
        if not tool:
            results.append({"tool": slug, "ok": False, "errors": [f"unknown tool: {slug}"]})
            continue
        results.append(install_tool(tool, dry_run=dry_run, repo=repo))
    return results


